static V modattr_(Sym n) {
    init();
    const std::string& s = n.str();
    if (s == "PETRIFIED_STUMP") return pm_native_style::PETRIFIED_STUMP;
    if (s == "SKY_COLORS") return pm_native_style::SKY_COLORS;
    if (s == "ROOT_PLANTS") return pm_native_style::ROOT_PLANTS;
    if (s == "LARGE_PLANTS") return pm_native_style::LARGE_PLANTS;
    if (s == "LARGE_ZOMBIES") return pm_native_style::LARGE_ZOMBIES;
    if (s == "SPLIT_HEADGEAR") return pm_native_style::SPLIT_HEADGEAR;
    if (s == "THROWERS") return pm_native_style::THROWERS;
    if (s == "PLANT_ZOMBIE_HEADS") return pm_native_style::PLANT_ZOMBIE_HEADS;
    if (s == "NativeArt") return cls_NativeArt();
    if (s == "PETRIFIED_TORCH") return pm_expansion_catalog::PETRIFIED_TORCH;
    if (s == "Path") return py::stdlib(SV("pathlib.Path"));
    if (s == "math") return py::stdlib(SV("math"));
    if (s == "sys") return py::stdlib(SV("sys"));
    return V();
}
static V modwrite_(const Args& A) {
    init();
    const std::string& s = A.pos.at(0).str();
    if (s == "PETRIFIED_STUMP") { pm_native_style::PETRIFIED_STUMP = A.pos.at(1); return V(true); }
    if (s == "SKY_COLORS") { pm_native_style::SKY_COLORS = A.pos.at(1); return V(true); }
    if (s == "ROOT_PLANTS") { pm_native_style::ROOT_PLANTS = A.pos.at(1); return V(true); }
    if (s == "LARGE_PLANTS") { pm_native_style::LARGE_PLANTS = A.pos.at(1); return V(true); }
    if (s == "LARGE_ZOMBIES") { pm_native_style::LARGE_ZOMBIES = A.pos.at(1); return V(true); }
    if (s == "SPLIT_HEADGEAR") { pm_native_style::SPLIT_HEADGEAR = A.pos.at(1); return V(true); }
    if (s == "THROWERS") { pm_native_style::THROWERS = A.pos.at(1); return V(true); }
    if (s == "PLANT_ZOMBIE_HEADS") { pm_native_style::PLANT_ZOMBIE_HEADS = A.pos.at(1); return V(true); }
    return V(false);
}
